import{_ as t,c as s,o as e,d as n}from"./chunks/framework.BHInEAh2.js";const h=JSON.parse('{"title":"36 tattvas table","description":"","frontmatter":{"title":"36 tattvas table","tags":"diagram"},"headers":[],"relativePath":"diagrams/tattvas/index.md","filePath":"diagrams/tattvas/index.md"}'),i={name:"diagrams/tattvas/index.md"};function d(o,a,c,r,l,p){return e(),s("div",null,[...a[0]||(a[0]=[n('<table id="tattvas" class="names" data-v-a9c63b29><tbody data-v-a9c63b29><tr data-v-a9c63b29><td colspan="4" data-v-a9c63b29><p class="sans" data-v-a9c63b29>परमशिव</p><p class="trans" data-v-a9c63b29>PARAMAŚIVA</p><p class="title" data-v-a9c63b29>Highest Shiva - the Source of All</p></td></tr><tr data-v-a9c63b29><td class="num" style="width:80px;" data-v-a9c63b29>1.</td><td style="width:80px;" data-v-a9c63b29><p class="sans" data-v-a9c63b29>शिव</p><p class="trans" data-v-a9c63b29>Śiva</p></td><td style="width:80%;" colspan="2" data-v-a9c63b29><span class="title" data-v-a9c63b29>Shiva</span> is beyond descriptions, yet it can be said that He is the true &quot;I&quot;. Shiva is full of Cicchakti (Cit + śakti) or the Power of Consciousness. Both Shiva and Shakti arise from Paramaśiva or the Supreme Shiva. In Paramaśiva, there is not even the subtle duality of Shiva-Shakti. All tattvas arise from this Supreme Reality.</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>2.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>शक्ति</p><p class="trans" data-v-a9c63b29>Śakti</p></td><td colspan="2" data-v-a9c63b29><span class="title" data-v-a9c63b29>Shakti</span> is also beyond description. And yet, it can be said that it is the true Being. Shiva and Shakti reveal the true &quot;I am&quot;. Shakti makes Shiva conscious of Himself, but there is no difference between them. Shakti is a very subtle &quot;tension&quot; on the infinite and motionless body of Shiva. From it, all other tattvas arise, in essence, they are its form. There is perfect unity between it and all other tattvas. She is full of Ānandaśakti or the Power of Bliss.</td></tr><tr data-v-a9c63b29><td colspan="4" data-v-a9c63b29><p class="sans" data-v-a9c63b29>अनाश्रितशिव</p><p class="trans" data-v-a9c63b29>ANĀŚRITAŚIVA</p><p class="translation" data-v-a9c63b29>Shiva Without Categories</p></td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>3.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>सदाशिव</p><p class="trans" data-v-a9c63b29>Sadāśiva</p> (सादाख्य Sādākhya)</td><td colspan="2" data-v-a9c63b29><span class="title" data-v-a9c63b29>Sadāśiva</span> — the abode of Icchāśakti or the Power of Will. Here, the universe appears in a hazy form. Consciousness takes the shape of &quot;I am This&quot; (&quot;I am this hazy Universe&quot;). The universe is just beginning to appear and therefore appears blurred. Since the universe is not yet fully formed, &quot;I&quot; predominates.</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>4.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>ईश्वर</p><p class="trans" data-v-a9c63b29>Īśvara</p></td><td colspan="2" data-v-a9c63b29><span class="title" data-v-a9c63b29>Īśvara</span> — the abode of Jñānaśakti or the Power of Knowledge. Here, a clear and distinct universe appears. Consciousness takes the form &quot;This is I&quot; (&quot;The distinct Universe is I&quot;). The universe is now fully manifested and therefore distinct. Since the universe is fully formed, &quot;This&quot; predominates. &quot;I&quot; is still present but is awestruck by the divine wonder of revealing Itself to Itself.</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>5.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>सद्विद्या</p><p class="trans" data-v-a9c63b29>Sadvidyā</p> (<span lang="sa" data-v-a9c63b29>शुद्धविद्या</span> Śuddhavidyā)</td><td colspan="2" data-v-a9c63b29><span class="title" data-v-a9c63b29>Sadvidyā</span> — the abode of Kriyāśakti or the Power of Action. Here, consciousness is perfectly balanced between &quot;I&quot; and &quot;This&quot;. &quot;This&quot; is the Universe. The awareness is: &quot;I am I, This is This&quot;. &quot;I&quot; is balanced with &quot;This&quot; and they both predominate in a way. This is unity in diversity, where there is a universe distinct from Shiva (&quot;I&quot;), yet there is an underlying unity between them.</td></tr><tr data-v-a9c63b29><td colspan="4" data-v-a9c63b29><p class="sans" data-v-a9c63b29>आणवमल</p><p class="trans" data-v-a9c63b29>ĀṆAVAMALA</p><p class="translation" data-v-a9c63b29>Anavamala or Primary Impurity, which precedes all other tattvas where differences and duality predominate. After Anavamala, two more malas or impurities arise: Māyīyamala <span lang="sa" data-v-a9c63b29>मायीयमल</span> and Kārmamala <span lang="sa" data-v-a9c63b29>कार्ममल</span>, which introduce differences and attachments to actions respectively.</p></td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>6.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>माया</p><p class="trans" data-v-a9c63b29>Māyā</p></td><td colspan="2" data-v-a9c63b29><span class="title" data-v-a9c63b29>Māyā</span> is Ignorance. The Māyā of Trika is not the same as in Vedānta. In Trika, Māyā is a tattva, or a &quot;real&quot; level of Creation. Māyā is responsible for veiling the essential nature of Shiva with a cloak of delusion. Māyā transforms the infinite Self into something full of limitations. Māyīya-mala and Karma-mala arise as a result of the action of Māyā-tattva. These two impurities fill activity with differences and attachments. Sometimes Māyā is considered as the &quot;sixth&quot; kañcuka or sheath, covering consciousness with a subtle but strong veil of ignorance.</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>7.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>कला</p><p class="trans" data-v-a9c63b29>Kalā</p></td><td width="80%" data-v-a9c63b29><span class="title" data-v-a9c63b29>Kalā</span> forms the notion of &quot;limited activity&quot; of consciousness veiled by Māyā. It is Kriyā-śakti (Omnipotence) that has undergone contraction. It introduces erroneous judgments: &quot;I am limited in actions,&quot; &quot;I cannot do this,&quot; &quot;I cannot do that,&quot; etc.</td><td style="width:10%;" rowspan="5" data-v-a9c63b29><p class="sans" data-v-a9c63b29>कञ्चुक</p><span class="trans" data-v-a9c63b29>KAÑCUKA</span> Kañcukas (sheaths) </td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>8.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>विद्या</p><p class="trans" data-v-a9c63b29>Vidyā</p></td><td data-v-a9c63b29><span class="title" data-v-a9c63b29>Vidyā</span> forms the notion of &quot;limited knowledge&quot; of consciousness veiled by Māyā. It is Jñāna-śakti (Omniscience) that has undergone contraction. It introduces erroneous judgments: &quot;I am limited in knowledge,&quot; &quot;I don&#39;t know this,&quot; &quot;I don&#39;t know that,&quot; etc.</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>9.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>राग</p><p class="trans" data-v-a9c63b29>Rāga</p></td><td data-v-a9c63b29><span class="title" data-v-a9c63b29>Rāga</span> forms the notion of &quot;limited will&quot; or desire. It is Ānanda-śakti (Bliss) that has undergone contraction. It introduces erroneous judgments: &quot;I want this,&quot; &quot;I don&#39;t want that,&quot; &quot;I like this,&quot; &quot;I don&#39;t like that,&quot; etc.</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>10.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>काल</p><p class="trans" data-v-a9c63b29>Kāla</p></td><td data-v-a9c63b29><span class="title" data-v-a9c63b29>Kāla</span> forms the notion of &quot;parts&quot; or time, leading the consciousness veiled by Māyā to the notion of time. It is Ānanda-śakti (Supreme Bliss) that has undergone contraction. It introduces erroneous judgments such as: &quot;I am not eternal and imperishable,&quot; &quot;I live only for a few years,&quot; &quot;I am old,&quot; &quot;I am young,&quot; etc.</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>11.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>नियति</p><p class="trans" data-v-a9c63b29>Niyati</p></td><td data-v-a9c63b29><span class="title" data-v-a9c63b29>Niyati</span> forms the notion of the connection between cause and effect, leading to the notion of a predetermined order of things. It is Citta-śakti (Power of Knowledge) that has undergone contraction. It introduces erroneous judgments such as: &quot;If I do this, I will get the corresponding result,&quot; &quot;I am worthy,&quot; &quot;I am sinful,&quot; etc.</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>12.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>पुरुष</p><p class="trans" data-v-a9c63b29>Puruṣa</p></td><td colspan="2" data-v-a9c63b29><span class="title" data-v-a9c63b29>Puruṣa</span> is the Self-Shiva who has undergone all the listed limitations (Kañcuka). Despite voluntary self-limitation, Shiva remains unchanged. This Puruṣa is the inner &quot;I&quot; of all beings. While it is the ultimate goal of Sāṃkhya philosophy, Trika considers it only an stage of Shakti&#39;s involution/evolution.</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>13.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>प्रकृति</p><p class="trans" data-v-a9c63b29>Prakṛti</p></td><td colspan="2" data-v-a9c63b29><span class="title" data-v-a9c63b29>Prakṛti</span> is simply a state in which all three qualities (Guṇa) remain completely balanced. The three gunas are Sattva, Rajas, and Tamas. They are also known as Jñāna-śakti, Ichchhā-śakti, and Kriyā-śakti respectively, having undergone another contraction. When the Supreme Witness (Śiva) is covered by the veil of Māyā and its kañcukas, He &quot;seems to&quot; become Puruṣa. This Puruṣa contemplates Śakti, and she now appears formed from three forces known as the gunas or qualities. Neither Śiva nor Śakti actually changes, but Śiva, through voluntary self-limitation, changes His perspective and begins to consider Himself as a limited soul.</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>14.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>बुद्धि</p><p class="trans" data-v-a9c63b29>Buddhi</p> (महत् Mahat)</td><td data-v-a9c63b29><span class="title" data-v-a9c63b29>Buddhi</span> is the first stage of Nature&#39;s evolution. It forms the determining faculty through which you choose the direction of your actions in life. Simply put, Buddhi is intellect. It is primarily a sattvic tattva, meaning that Jñāna (knowledge) predominates in it. Buddhi is also the principle that allows you to abstractly catalog specific objects, animals, or personalities into clear categories. For example, &quot;This is a dog,&quot; &quot;This is a hat.&quot;</td><td rowspan="3" data-v-a9c63b29><p class="sans" data-v-a9c63b29>अन्तःकरण</p><p class="trans" data-v-a9c63b29>ANTAḤKARAṆA</p> Internal (mental) organ</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>15.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>अहङ्कार</p><p class="trans" data-v-a9c63b29>Ahaṅkāra</p> (अस्मिता Asmitā)</td><td data-v-a9c63b29><span class="title" data-v-a9c63b29>Ahaṅkāra</span> is the second stage of Nature&#39;s evolution. It forms the awareness of the limited &quot;I&quot;. Simply put, Ahaṅkāra is the ego. Manas, the indriyas, and the tanmatras not only arise from it but are constantly sustained by asmitā. Its main characteristic is &quot;self-identification.&quot; It makes the pure Self a doer, &quot;Ahaṅkāra&quot; means &quot;I-doer.&quot; It connects the pure Self, which is merely a witness, with a specific action or concept. For example, &quot;I do my work,&quot; &quot;I build buildings,&quot; &quot;I love you,&quot; &quot;I am poor,&quot; etc. Let&#39;s remove ahaṅkāra, and the sentences will look like this: &quot;Work is done,&quot; &quot;Buildings are built,&quot; &quot;There is love for you,&quot; &quot;Poverty exists,&quot; etc. Ahaṅkāra also gives everything volume. This is the reason for this three-dimensional universe. The ego is primarily rajasic.</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>16.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>मनस्</p><p class="trans" data-v-a9c63b29>Manas</p></td><td data-v-a9c63b29><span class="title" data-v-a9c63b29>Manas</span> is the third stage of Nature&#39;s evolution. Simply put, manas is the mind. The mind forms a network of thoughts. The mind is the source and controller of the Jñānendriyas (Senses of Perception) and the Karmendriyas (Senses of Action). One of its functions is to straighten and color the primitive picture formed by the retina. The mind works in two-dimensional space, not three-dimensional space. Setting the third dimension is the work of ahaṅkāra. The mind is primarily tamasic.</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>17.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>श्रोत्र</p><p class="trans" data-v-a9c63b29>Śrotra</p> (श्रवण Śravaṇa)</td><td data-v-a9c63b29><span class="title" data-v-a9c63b29>Śrotra</span> refines the Śabda-tanmātra into intelligible vibration. Classical teachers liken it to a conch cavity that gathers the ocean’s roar into a single tone a yogin can track back to the inner nāda; disciplined hearing converts every sound into instruction.</td><td rowspan="5" data-v-a9c63b29><p class="sans" data-v-a9c63b29>ज्ञानेन्द्रिय</p><p class="trans" data-v-a9c63b29>JÑĀNENDRIYA</p> Senses of Perception (primarily sattvic)</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>18.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>त्वक्</p><p class="trans" data-v-a9c63b29>Tvak</p></td><td data-v-a9c63b29><span class="title" data-v-a9c63b29>Tvak</span> stretches as a vāyu-woven net over the skin, translating Sparśa into tactile knowledge. A breeze on the cheek or sacred ash warming the hand becomes data about prāṇa currents, guiding the yogin in regulating contact.</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>19.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>चक्षुस्</p><p class="trans" data-v-a9c63b29>Cakṣus</p></td><td data-v-a9c63b29><span class="title" data-v-a9c63b29>Cakṣus</span> acts as a steady lamp that turns the Rūpa-tanmātra into discernible form. When light rests on a still lake and returns as an image, it illustrates how vision offers the seer precise information for contemplation and alignment.</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>20.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>जिह्वा</p><p class="trans" data-v-a9c63b29>Jihvā</p> (रसना Rasanā)</td><td data-v-a9c63b29><span class="title" data-v-a9c63b29>Jihvā</span> assays the Rasa-tanmātra, offering analytic feedback on nourishment. Tasting consecrated offerings after worship or sensing the bitterness that signals imbalance trains the practitioner to read flavors as indices of prāṇa assimilation and ethical restraint.</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>21.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>घ्राण</p><p class="trans" data-v-a9c63b29>Ghrāṇa</p></td><td data-v-a9c63b29><span class="title" data-v-a9c63b29>Ghrāṇa</span> decodes Gandha by reading the vibrational signatures of the solid particles and aromatic gases that meet the nose. Distinguishing sandalwood molecules from acrid smoke, or rain-washed soil from decay, teaches the yogin to monitor purity, imbalance, and the precise state of the elemental field.</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>22.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>वाक्</p><p class="trans" data-v-a9c63b29>Vāk</p></td><td data-v-a9c63b29><span class="title" data-v-a9c63b29>Vāk</span> channels the four levels of speech into audible expression. Whether shaping a precise instruction or articulating Oṃ, it demonstrates how consciousness descends from Paśyantī to Vaikharī, allowing deliberate words to mold circumstance.</td><td rowspan="5" data-v-a9c63b29><p class="sans" data-v-a9c63b29>कर्मेन्द्रिय</p><span class="trans" data-v-a9c63b29>KARMENDRIYA</span> Senses of Action (primarily rajasic) </td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>23.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>पाणि</p><p class="trans" data-v-a9c63b29>Pāṇi</p></td><td data-v-a9c63b29><span class="title" data-v-a9c63b29>Pāṇi</span> grants the faculty to grasp, mould, and bestow. Mudrā, almsgiving, or craftwork all show how intent moves outward through the palm, teaching that mastery of action requires precision in both taking and releasing.</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>24.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>पाद</p><p class="trans" data-v-a9c63b29>Pāda</p></td><td data-v-a9c63b29><span class="title" data-v-a9c63b29>Pāda</span> executes locomotion so that resolve becomes trajectory. Circumambulating a shrine or pacing a field illustrates how direction, rhythm, and balance of the feet translate inner vows into geographic fact.</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>25.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>उपस्थ</p><p class="trans" data-v-a9c63b29>Upastha</p></td><td data-v-a9c63b29><span class="title" data-v-a9c63b29>Upastha</span> governs procreation and refined enjoyment. Its disciplined use transmutes sensual charge into ojas, confirming the teaching that continuity of lineage and continuity of awareness depend on the same reservoir of power.</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>26.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>पायु</p><p class="trans" data-v-a9c63b29>Pāyu</p></td><td data-v-a9c63b29><span class="title" data-v-a9c63b29>Pāyu</span> administers elimination, maintaining the altar of the body. By timing release after absorption, it illustrates the Trika emphasis on cycles—intake, transformation, offering, and clearance—so the next act of worship can proceed.</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>27.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>शब्द</p><p class="trans" data-v-a9c63b29>Śabda</p></td><td data-v-a9c63b29><span class="title" data-v-a9c63b29>Śabda</span> is the subtle sound-element, the potential of vibration before articulation. Meditative attention to the pause between breaths reveals this tanmātra as the template from which mantra and speech later unfold.</td><td rowspan="5" data-v-a9c63b29><p class="sans" data-v-a9c63b29>तन्मात्र</p><span class="trans" data-v-a9c63b29>TANMĀTRA</span> Subtle elements (primarily tamasic) </td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>28.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>स्पर्श</p><p class="trans" data-v-a9c63b29>Sparśa</p></td><td data-v-a9c63b29><span class="title" data-v-a9c63b29>Sparśa</span> is tactile potential prior to objectification. It is experienced as the first stirring of vāyu that precedes contact, training one to notice impulses before they harden into sensation.</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>29.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>रूप</p><p class="trans" data-v-a9c63b29>Rūpa</p></td><td data-v-a9c63b29><span class="title" data-v-a9c63b29>Rūpa</span> is luminous form, the chromatic hint before definite objects appear. Commentaries compare it to dawn light announcing the sun; contemplating it refines vision to perceive form as gradations of Śakti.</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>30.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>रस</p><p class="trans" data-v-a9c63b29>Rasa</p></td><td data-v-a9c63b29><span class="title" data-v-a9c63b29>Rasa</span> is taste in its pure idea, the matrix from which sweet, bitter, or pungent emerge. Recognizing this tanmātra teaches that every flavor, pleasant or austere, is a coded instruction from the body to awareness.</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>31.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>गन्ध</p><p class="trans" data-v-a9c63b29>Gandha</p></td><td data-v-a9c63b29><span class="title" data-v-a9c63b29>Gandha</span> is scent as primordial memory. The aroma of til oil on a lamp or freshly turned soil evokes earth&#39;s body before any form appears, anchoring mind to matter.</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>32.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>आकाश</p><p class="trans" data-v-a9c63b29>Ākāśa</p></td><td data-v-a9c63b29><span class="title" data-v-a9c63b29>Ākāśa</span> is the spacious matrix that hosts sound and form. Like a stainless sky accommodating moon and storm alike, it exemplifies how awareness can contain phenomena without contraction.</td><td rowspan="5" data-v-a9c63b29><p class="sans" data-v-a9c63b29>महाभूत</p><span class="trans" data-v-a9c63b29>MAHĀBHŪTA</span> Gross elements (primarily tamasic) </td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>33.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>वायु</p><p class="trans" data-v-a9c63b29>Vāyu</p></td><td data-v-a9c63b29><span class="title" data-v-a9c63b29>Vāyu</span> is the mobile principle that animates prāṇa. Observing the banner that moves only when wind passes illustrates how life-force becomes evident through motion, inviting regulation via breath practices.</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>34.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>अग्नि</p><p class="trans" data-v-a9c63b29>Agni</p> (तेजस् Tejas)</td><td data-v-a9c63b29><span class="title" data-v-a9c63b29>Agni</span> is transformative fire, whether as altar flame, digestive heat, or sudden insight. It shows how offerings—food, thought, or karma—are transmuted into energy that can ascend.</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>35.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>आपस्</p><p class="trans" data-v-a9c63b29>Āpas</p></td><td data-v-a9c63b29><span class="title" data-v-a9c63b29>Āpas</span> is the principle of cohesion and flow. Rivers, tears, and the mirror-like pond demonstrate how this element soothes, carries memory, and adapts form without losing continuity.</td></tr><tr data-v-a9c63b29><td class="num" data-v-a9c63b29>36.</td><td data-v-a9c63b29><p class="sans" data-v-a9c63b29>पृथिवी</p><p class="trans" data-v-a9c63b29>Pṛthivī</p></td><td data-v-a9c63b29><span class="title" data-v-a9c63b29>Pṛthivī</span> is solidity, the altar on which the other elements perform. Mountains, clay under a potter’s palm, or the structure of the body all manifest its lesson: stability enables every rite of consciousness.</td></tr></tbody></table>',1)])])}const b=t(i,[["render",d],["__scopeId","data-v-a9c63b29"]]);export{h as __pageData,b as default};
